import{_ as i,C as s,c as l,o as u,a3 as n,j as t,G as a,a as o}from"./chunks/framework.Dokpd4od.js";const _=JSON.parse('{"title":"Bills of Material","description":"","frontmatter":{},"headers":[],"relativePath":"master/manufacturing/products/bills-of-material.md","filePath":"master/manufacturing/products/bills-of-material.md","lastUpdated":1791533670000}'),g={name:"master/manufacturing/products/bills-of-material.md"};function m(d,e,p,c,h,f){const r=s("ImagePopup");return u(),l("div",null,[e[10]||(e[10]=n('<h1 id="bills-of-material" tabindex="-1">Bills of Material <a class="header-anchor" href="#bills-of-material" aria-label="Permalink to &quot;Bills of Material&quot;">​</a></h1><p>A <strong>Bill of Material (BoM)</strong> is the recipe of a finished product. It defines <strong>which components</strong> are required to produce <strong>one unit</strong> of an item, <strong>in what quantity</strong>, <strong>through which operations</strong>, and <strong>on which work centers</strong>.<br> The BoM is the single source of truth used by every manufacturing order to:</p><ul><li>Reserve raw materials.</li><li>Generate work orders.</li><li>Compute lead time and cost.</li><li>Track consumption and produced quantities.</li></ul><p><strong>Use Case:</strong><br> Create a BoM for every product that is <strong>manufactured</strong> (instead of purchased) or every <strong>kit</strong> assembled from existing components for sale or delivery.</p><blockquote><p><strong>In simple words:</strong> A Bill of Material is a <strong>recipe</strong>. Just like a cake recipe lists flour, sugar, and eggs, a BoM lists the components and quantities needed to build one finished product.</p></blockquote><blockquote><p><strong>Where it fits:</strong> The BoM is used by the <a href="./../operations/manufacturing-orders.html">Manufacturing Order</a> to know what to consume and which <a href="./../operations/work-orders.html">Work Orders</a> to generate. Make sure the <a href="./products.html">finished product and its components</a> already exist before creating a BoM.</p></blockquote><h2 id="steps-to-create-a-new-bill-of-material" tabindex="-1">Steps to Create a New Bill of Material <a class="header-anchor" href="#steps-to-create-a-new-bill-of-material" aria-label="Permalink to &quot;Steps to Create a New Bill of Material&quot;">​</a></h2>',7)),t("ol",null,[t("li",null,[e[0]||(e[0]=t("p",null,[o("Navigate to "),t("strong",null,[t("code",null,"Manufacturing → Products → Bills of Materials")]),o(" as shown below:")],-1)),a(r,{src:"/images1/manufacturing/bom_navigation.png",alt:"Bills of Materials Navigation"})]),t("li",null,[e[1]||(e[1]=n('<p>Fill in the following details:</p><h4 id="general-section" tabindex="-1">General Section <a class="header-anchor" href="#general-section" aria-label="Permalink to &quot;General Section&quot;">​</a></h4><ul><li><strong><em>Reference:</em></strong> Unique identifier for the BoM (e.g. <code>BOM-001</code>). Useful when a product has multiple BoMs.</li><li><strong><em>Product:</em></strong> The finished product this BoM produces.</li><li><strong><em>Product Variant:</em></strong> If the product has variants, choose the specific variant this BoM applies to. Leave empty for the BoM to apply to <strong>all</strong> variants.</li><li><strong><em>Quantity:</em></strong> The number of finished units produced when this BoM is consumed once (usually <code>1</code>).</li><li><strong><em>UOM:</em></strong> Unit of measure for the produced quantity (e.g. <em>Units</em>, <em>Kilograms</em>).</li><li><strong><em>Company:</em></strong> Company that owns this BoM.</li></ul>',3)),a(r,{src:"/images1/manufacturing/bom_general_section.png",alt:"BoM General Section"}),e[2]||(e[2]=n('<h4 id="miscellaneous-section" tabindex="-1">Miscellaneous Section <a class="header-anchor" href="#miscellaneous-section" aria-label="Permalink to &quot;Miscellaneous Section&quot;">​</a></h4><p>Fine-tune how the BoM behaves on the manufacturing order.</p><ul><li><strong><em>Manufacturing Readiness:</em></strong> Choose when the manufacturing order should be marked <strong>Ready</strong>: <ul><li><strong>When components are available</strong> – Ready as soon as all materials are in stock.</li><li><strong>When the components for the 1st operation are available</strong> – Ready when only the first operation&#39;s components are on hand (useful for long routings).</li></ul></li><li><strong><em>Routing:</em></strong> Display-only summary of the operations sequence linked to this BoM.</li><li><strong><em>Flexible Consumption:</em></strong> Controls how strictly the system enforces the planned consumption: <ul><li><strong>Allowed</strong> – Operators can consume more or less without warning.</li><li><strong>Allowed with Warning</strong> – Variations are allowed but a warning is shown.</li><li><strong>Blocked</strong> – Quantities must match exactly.</li></ul></li><li><strong><em>Operation Dependencies:</em></strong> Enable to use the <strong>Blocked By</strong> relationships configured on individual operations. Requires <em>Work Order Dependencies</em> to be enabled in settings.</li><li><strong><em>Manufacturing Lead Time (days):</em></strong> Overrides the global lead time configured in <strong>Manage Planning</strong> for this specific BoM.</li><li><strong><em>Days to prepare Manufacturing Order:</em></strong> Extra preparation days needed before launching production based on this BoM.</li></ul>',3)),a(r,{src:"/images1/manufacturing/bom_miscellaneous_tab.png",alt:"BoM Miscellaneous Tab"})]),e[3]||(e[3]=t("li",null,[t("p",null,[o("Configure the "),t("strong",null,"tabs"),o(" below the general section.")])],-1))]),e[11]||(e[11]=n('<h3 id="components-tab" tabindex="-1">Components Tab <a class="header-anchor" href="#components-tab" aria-label="Permalink to &quot;Components Tab&quot;">​</a></h3><p>The <strong>Components</strong> tab lists every raw material or sub-assembly required to produce one unit of the finished product.</p><p>Click <strong>Add a line</strong> and fill:</p><ul><li><strong><em>Component:</em></strong> Select an existing product. You can also create a new one inline by providing <strong>Name</strong>, <strong>Type</strong>, <strong>Category</strong>, <strong>Company</strong>, and <strong>UOM</strong>.</li><li><strong><em>Apply on Variants:</em></strong> Restrict this component to specific variants (e.g. only the <em>Red</em> variant needs the red dye).</li><li><strong><em>Consumed in Operation:</em></strong> Select the operation that consumes this component. Helps allocate raw material withdrawal to the right work order.</li><li><strong><em>Highlight Consumption:</em></strong> Toggle to highlight critical components on the manufacturing order for operator attention.</li><li><strong><em>Quantity:</em></strong> Quantity of the component required for <strong>one unit</strong> of the finished product.</li><li><strong><em>Product Unit of Measure:</em></strong> UOM of the component (auto-filled from the product master).</li></ul>',4)),a(r,{src:"/images1/manufacturing/bom_components_tab.png",alt:"BoM Components Tab"}),e[12]||(e[12]=n('<h3 id="operations-tab" tabindex="-1">Operations Tab <a class="header-anchor" href="#operations-tab" aria-label="Permalink to &quot;Operations Tab&quot;">​</a></h3><p>The <strong>Operations</strong> tab defines the <strong>routing</strong> — every shop-floor step required to assemble the finished product. Available only when <strong>Work Orders</strong> is enabled in <a href="./../settings.html">Manufacturing Settings</a>. Each line links an <a href="./../configurations/operations.html">Operation</a> to a <a href="./../configurations/work-centers.html">Work Center</a>.</p><p>Click <strong>Add a line</strong> to add a new operation, or click <strong>Copy Existing Operations</strong> to import operations from another BoM.</p><p>For each operation, configure:</p><ul><li><strong><em>Operation:</em></strong> Name of the step (e.g. <em>Cutting</em>, <em>Assembly</em>).</li><li><strong><em>Work Center:</em></strong> Station where the operation runs.</li><li><strong><em>Duration Computation:</em></strong> Either <em>Set Manually</em> or <em>Compute Based on Tracked Time</em>.</li><li><strong><em>Computed on last … work orders:</em></strong> When automatic computation is selected, the number of past work orders averaged.</li><li><strong><em>Company:</em></strong> Company owning the operation.</li><li><strong><em>Apply on Variants:</em></strong> Restrict the operation to selected variants.</li><li><strong><em>Duration (minutes):</em></strong> Default time required when manual mode is used.</li></ul><p>Use the <strong>Edit Operation</strong> action on a line to open the full operation form (including worksheet and dependencies).</p>',6)),a(r,{src:"/images1/manufacturing/bom_operations_tab.png",alt:"BoM Operations Tab"}),e[13]||(e[13]=n('<ol start="4"><li><p><strong>Action Buttons:</strong></p><ul><li><strong>Create</strong> – Save and open the BoM record.</li><li><strong>Create &amp; Create Another</strong> – Save and open a blank form to create another BoM.</li><li><strong>Cancel</strong> – Discard the entry.</li></ul></li></ol><h2 id="bill-of-material-view-page" tabindex="-1">Bill of Material View Page <a class="header-anchor" href="#bill-of-material-view-page" aria-label="Permalink to &quot;Bill of Material View Page&quot;">​</a></h2><p>After creation, you land on the <strong>BoM View Page</strong> with all tabs and a few extra controls.</p>',3)),t("ul",null,[e[5]||(e[5]=t("li",null,[t("p",null,[t("strong",null,"View:"),o(" Read-only summary of the BoM, including general info, components, operations, by-products, and the miscellaneous configuration.")])],-1)),e[6]||(e[6]=t("li",null,[t("p",null,[t("strong",null,"Edit:"),o(" Modify any field.")])],-1)),t("li",null,[e[4]||(e[4]=t("p",null,[t("strong",null,"Overview:"),o(" Opens the "),t("strong",null,"BoM Overview"),o(" report — a hierarchical, exploded view of the BoM showing every level of components, sub-BoMs, costs, and lead times.")],-1)),a(r,{src:"/images1/manufacturing/bom_overview_page.png",alt:"BoM Overview Page"})]),e[7]||(e[7]=t("li",null,[t("p",null,[t("strong",null,"Print:"),o(" Export the BoM as a printable document.")])],-1)),e[8]||(e[8]=t("li",null,[t("p",null,[t("strong",null,"Duplicate:"),o(" Create a copy to quickly build a variant BoM.")])],-1)),e[9]||(e[9]=t("li",null,[t("p",null,[t("strong",null,"Archive / Delete:"),o(" Remove a BoM that is no longer used.")])],-1))]),e[14]||(e[14]=n('<h2 id="list-view-—-filters-actions" tabindex="-1">List View — Filters &amp; Actions <a class="header-anchor" href="#list-view-—-filters-actions" aria-label="Permalink to &quot;List View — Filters &amp; Actions&quot;">​</a></h2><p>The <strong>Bills of Materials</strong> list view shows: <strong>Reference</strong>, <strong>Product</strong>, <strong>Quantity</strong>, <strong>UOM</strong>, <strong>BoM Type</strong>, and <strong>Company</strong>.</p><p>You can:</p><ul><li><strong>Filter by:</strong> Product, BoM Type, or Company.</li><li><strong>Bulk Actions:</strong> Archive, restore, or permanently delete selected BoMs.</li></ul><h3 id="summary" tabindex="-1">Summary <a class="header-anchor" href="#summary" aria-label="Permalink to &quot;Summary&quot;">​</a></h3><p>A well-built BoM ensures that:</p><ul><li>The right components are reserved automatically when a <a href="./../operations/manufacturing-orders.html">Manufacturing Order</a> is confirmed.</li><li>Operators see the right <a href="./../operations/work-orders.html">Work Orders</a>, on the right <a href="./../configurations/work-centers.html">Work Centers</a>, in the right sequence.</li><li>Costs and lead times are computed accurately.</li><li>By-products and kits are handled with the same data model as standard production.</li></ul><blockquote><p><strong>Next step:</strong> Once your BoM is ready, you can launch production by creating a <a href="./../operations/manufacturing-orders.html">Manufacturing Order</a>.</p></blockquote>',8))])}const y=i(g,[["render",m]]);export{_ as __pageData,y as default};
